const body = $input.first().json;

// Eventos relevantes de Chatwoot
// - conversation_created: nueva conversación (inbound)
// - conversation_status_changed: cambio de estado (pendiente → asignado)
// - label_created: se añadió una etiqueta (ej: 'requires_human')
const event = body.event || body.type || '';
const validEvents = ['conversation_created', 'conversation_updated', 'label_created', 'conversation_status_changed'];

if (!validEvents.includes(event)) {
  return [{ json: { skip: true, reason: 'event_ignored: ' + event } }];
}

const conv = body.conversation || body || {};
const contact = conv.meta?.sender || conv.contact || body.contact || {};
const agent = conv.meta?.assignee || conv.assignee || null;
const labels = conv.labels || body.labels || [];

// Solo notificar si hay etiqueta de humano o si la IA pausó
const needsHuman = labels.includes('requires_human') || 
                   labels.includes('human_requested') ||
                   conv.status === 'pending' ||
                   (event === 'conversation_created' && !agent);

if (!needsHuman) {
  return [{ json: { skip: true, reason: 'no_human_needed', status: conv.status, labels } }];
}

const contactName  = contact.name || 'Cliente';
const contactPhone = (contact.phone_number || '').replace(/\D/g, '').replace(/^1/, '');
const convId       = conv.id || body.conversation_id || '';
const convUrl      = `${$env.CHATWOOT_EXTERNAL_URL || 'https://chat.tudominio.com'}/app/accounts/1/conversations/${convId}`;
const inboxName    = conv.inbox_name || conv.channel || 'WhatsApp';
const lastMessage  = conv.last_activity_at || '';

// Teléfono del agente a notificar (Roy o el equipo)
const agentPhone = $env.AGENT_WHATSAPP || $env.TWILIO_TRANSFER_NUMBER || '';
const agentPhoneClean = agentPhone.replace(/\D/g, '').replace(/^1/, '');

if (!agentPhoneClean) {
  return [{ json: { skip: true, reason: 'no_agent_phone_configured' } }];
}

const notifMsg = `🔴 *Atención requerida* — ${inboxName}\n\n` +
  `👤 Cliente: *${contactName}*\n` +
  (contactPhone ? `📱 Teléfono: +1${contactPhone}\n` : '') +
  `💬 Conversación: ${convUrl}\n\n` +
  `El cliente pidió hablar con una persona. Responde en Chatwoot o llámalo directamente.`;

return [{
  json: {
    skip: false,
    agentPhone: agentPhoneClean,
    contactName,
    contactPhone,
    convId,
    convUrl,
    notifMsg,
    event
  }
}];
